# Six fixed-protocol training seeds; synchronous Save & Run All.
from pathlib import Path
import os,sys,json,base64,gzip,shutil,subprocess
os.environ['CUDA_VISIBLE_DEVICES']='0'
os.environ['TOKENIZERS_PARALLELISM']='false'
import kagglehub
saved=Path(kagglehub.notebook_output_download('trinashih/3beethoven-v0-2/versions/37'))
source=min((p for p in saved.rglob('3Beethoven_v19') if (p/'scripts/run_stats_v0_19.py').exists()),key=lambda p:len(p.parts))
repo=Path('/kaggle/working/seed_repo')
shutil.copytree(source,repo,dirs_exist_ok=True,ignore=shutil.ignore_patterns('__pycache__','.git'))
for rel,content in json.loads(gzip.decompress(base64.b64decode(''))).items():
 p=repo/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(content)
subprocess.run([sys.executable,'-m','pip','install','--quiet','transformers==5.0.0','peft==0.19.1','bitsandbytes==0.50.2','datasets==5.0.0','accelerate==1.13.0'],check=True)
subprocess.run([sys.executable,str(repo/'scripts/run_training_seed_replication.py')],cwd=repo,check=True)
